import {questionGroups,questionGuidance} from './catalyst-question-scope.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const when=v=>v&&Number.isFinite(Date.parse(v))?new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Seoul'}).format(new Date(v))+' KST':'날짜 미확인';
const market=m=>({KR:'한국',US:'미국'}[m]||m);
function link(url,label){try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password||u.port||/^[\d.]+$|:|localhost|\.local$|\.internal$/i.test(u.hostname)||!u.hostname.includes('.'))return esc(label);return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;}catch{return esc(label);}}
function sourcesMarkup(sources){return sources.map(s=>`<article class="cf-source"><h4>${link(s.url,s.title)}</h4><p class="cf-meta">${esc(s.publisher)} · 발행 ${esc(s.publishedAt||'날짜 미확인')}</p>${(s.quotes||[]).map(q=>`<blockquote>${esc(q)}</blockquote>`).join('')}</article>`).join('');}
function candidate(c){return `<article class="surface cf-delivery-card"><div class="cf-card-head"><div><span class="cf-badge">${esc(c.category)}</span><h3><a href="${esc(c.asset.href||'#')}" data-nav>${esc(c.asset.name)}</a></h3><p class="cf-meta">${esc(market(c.asset.market))} · ${esc(c.asset.symbol)}</p></div><span class="cf-importance">${esc(c.importance)}</span></div><p class="cf-product">${esc(c.product)}</p><p class="cf-share">${esc(c.shareBasis)}</p><p>${esc(c.explanation)}</p><p class="cf-meta">변화 민감도 ${esc(c.sensitivity)} · ${esc(c.evidenceLevel)}</p>${c.condition?`<p class="cf-condition">${esc(c.condition)}</p>`:''}<p class="cf-missing">더 확인할 점 · ${esc(c.primaryMissing)}</p><details class="cf-evidence-detail"><summary>${esc(c.asset.name)} 근거 보기</summary><h4>확인된 사업</h4><blockquote>${esc(c.details.business||'확인된 원문이 없습니다.')}</blockquote><h4>공시 매출 구성</h4>${c.revenueBreakdown?.length?`<ul>${c.revenueBreakdown.map(x=>`<li>${esc(x.label)}</li>`).join('')}</ul>`:`<p>${esc(c.shareBasis)}</p>`}${c.details.materiality?`<blockquote>${esc(c.details.materiality)}</blockquote>`:''}${c.details.businessProfile?.length?`<h4>기업 사업·매출 DB</h4><p class="cf-meta">공시 원문 항목입니다. 질문의 세부 제품 매출로 바꾸지 않습니다.</p><ul>${c.details.businessProfile.map(o=>`<li>${esc(o.label)} · ${esc(o.amountExact??"금액 미확인")} ${esc(o.unit||"")} · ${o.percent===null||o.percent===undefined?"비중 미확인":esc(Number(o.percent).toLocaleString('ko-KR',{maximumFractionDigits:2}))+"%"} · ${esc(o.period)} · ${link(o.sourceUrl,'원문')}</li>`).join("")}</ul>`:""}<h4>수혜 가능성 판단 <small>분석·추론</small></h4><p>${esc(c.details.inference)} ${esc(c.sensitivityBasis)}</p><h4>추가 확인</h4><ul>${c.missing.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="cf-meta">추가 조사 · ${esc(c.details.additionalResearch)}</p><h4>출처 · ${c.details.sources.length}개 문서</h4>${sourcesMarkup(c.details.sources)}</details></article>`;}
function compare(c){return `<div class="cf-compare-row" role="row">${[c.asset.name,c.category,c.product,c.importance,c.shareBasis,c.sensitivity,c.evidenceLevel].map((value,i)=>`<div role="cell"><span class="cf-mobile-label">${['기업','분야','관련 제품','사업 중요도','매출 비중·근거','변화 민감도','근거 수준'][i]}</span>${esc(value)}</div>`).join('')}</div>`;}
export function deliveryMarkup(r,{marketFilter='ALL',sort='default'}={}){
 if(r.message&&!r.groups)return `<section class="surface cf-answer" role="status"><p class="cf-meta">질문: ${esc(r.query)}</p><h2>${esc(r.message)}</h2>${r.guidance?`<p>${esc(r.guidance)}</p>`:''}${r.pending?'<p>이 화면을 다시 열어도 새 분석을 시작하지 않습니다.</p>':''}</section>`;
 if(r.supported===false)return `<section class="surface"><h2>분석 범위 안내</h2><p>${esc(r.message)}</p><a href="/catalyst?legacy=1" data-nav>기존 사건·자산 분석 기록 보기 →</a></section>`;
 const select=xs=>{const a=xs.filter(c=>marketFilter==='ALL'||c.asset.market===marketFilter);return sort==='name'?a.sort((x,y)=>x.asset.name.localeCompare(y.asset.name)):a;};
 const core=select(r.groups.core),related=select(r.groups.related),unknown=select(r.groups.unknown),comparison=[...core,...related,...unknown];
 return `<section class="surface cf-answer"><div class="cf-meta"><span class="cf-badge">${r.scope?.hypothetical===false?'주제별 사업 탐색':'조건형 영향 탐색'}</span><span>저장된 분석 · ${esc(when(r.asOf))}</span>${r.freshness.stale?'<span>최신 재조사 전</span>':''}</div><h2>${esc(r.summary)}</h2>${marketFilter!=='ALL'?`<p class="cf-meta">전체 분석 요약 · 아래 후보는 ${esc(market(marketFilter))}만 표시합니다.</p>`:''}<p class="cf-meta">질문: ${esc(r.query)}</p></section><section class="cf-core"><h2>핵심 수혜 후보 <small>${core.length}</small></h2>${core.length?core.slice(0,3).map(candidate).join(''):'<p class="surface">현재 자료에서 사업 중요도까지 확인한 핵심 후보는 없습니다.</p>'}${core.length>3?`<details class="cf-more"><summary>${Math.min(2,core.length-3)}개 더 보기</summary>${core.slice(3,5).map(candidate).join('')}</details>`:''}</section><section class="surface cf-comparison"><h2>후보 비교</h2><p class="cf-meta">사업 비중의 범위가 다른 경우 수치만으로 우열을 정하지 않습니다.</p><div class="cf-compare" role="table" aria-label="후보 비교"><div class="cf-compare-row cf-compare-head" role="row">${['기업','분야','관련 제품','사업 중요도','매출 비중·근거','변화 민감도','근거 수준'].map(t=>`<div role="columnheader">${t}</div>`).join('')}</div>${comparison.slice(0,5).map(compare).join('')}</div>${comparison.length>5?`<details><summary>비교 ${comparison.length-5}개 더 보기</summary><div class="cf-compare">${comparison.slice(5).map(compare).join('')}</div></details>`:''}</section>${[['관련 사업 보유 기업',related],['비중 추가 확인',unknown]].map(([title,items])=>`<details class="surface cf-group"><summary>${title} · ${items.length}개</summary>${items.map(candidate).join('')||'<p>이 분류에 해당하는 후보가 없습니다.</p>'}</details>`).join('')}<details class="surface cf-limits"><summary>근거·분석 한계</summary><ul>${r.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="cf-meta">확인 대상 ${r.coverage.investigated}개 기업 · 사업 중요도 조사 ${r.coverage.materialityInvestigated}개 · 기본 결과 제외 ${r.coverage.excluded}개</p><p class="cf-meta">${esc(r.materialityPolicyVersion)} · ${r.freshness.reranked?'저장 근거를 현재 정책으로 재분류':'현재 정책 적용'}</p>${sourcesMarkup(r.sources)}</details>`;
}
const examples=questionGroups[0].examples;
export function questionExamplesMarkup(){return `<div class="cf-question-topics" role="group" aria-label="질문 예시 분야">${questionGroups.map((g,i)=>`<button type="button" data-question-group="${g.id}" aria-pressed="${i===0}">${esc(g.label)}</button>`).join('')}</div><div class="cf-examples" id="cf-examples">${examples.map(q=>`<button type="button" data-question="${esc(q)}">${esc(q)}</button>`).join('')}</div><p class="cf-meta" id="cf-question-guidance" aria-live="polite">${esc(questionGuidance(''))}</p>`;}
export function mountResearchDelivery(root){
 let dead=false,current=null,admin=false,ready=false,activeId=null,timer;const abort=new AbortController();
 root.innerHTML=`<div class="cf-shell cf-delivery"><header class="page-heading"><div><div class="eyebrow">CATALYST & IMPACT FINDER</div><h1>수혜주 탐색</h1><p>산업·경제 변화와 기업의 사업 연결을 확인합니다.</p></div></header><form class="surface cf-form"><label for="cf-question">어떤 변화와 관련된 기업을 찾으세요?</label><div class="cf-query"><textarea id="cf-question" rows="2" maxlength="500" minlength="2" required placeholder="${examples[0]}"></textarea><button type="submit">저장 분석 찾기 →</button></div>${questionExamplesMarkup()}<details class="cf-options"><summary>시장·종목·참고 URL (선택)</summary><label for="cf-market">분석 시장</label><select id="cf-market"><option value="ALL">한국·미국</option><option value="KR">한국</option><option value="US">미국</option><option value="CRYPTO">가상화폐 · 별도 모델</option></select><label for="cf-hint">질문에 덧붙일 종목·참고 URL</label><input id="cf-hint" type="search" maxlength="200" placeholder="종목명·티커 또는 https:// 원문 주소"><p class="cf-meta">선택 사항입니다. 참고 주소가 있어도 원문 확인을 통과한 내용만 사용합니다.</p><a href="/catalyst?legacy=1" data-nav>기존 사건·가격·코인 분석 기록 →</a></details><p id="cf-message" role="status"></p><div id="cf-actions" hidden><button type="button" class="primary-button" id="cf-new">새 분석 요청</button><button type="button" class="secondary-button" id="cf-cancel" hidden>분석 취소</button><p class="cf-meta">관리자 요청 · 정해진 예산으로 한 건만 실행합니다.</p></div></form><div class="cf-delivery-filters" hidden><label>결과 시장 <select id="cf-filter"><option value="ALL">전체</option><option value="KR">한국</option><option value="US">미국</option></select></label><label>정렬 <select id="cf-sort"><option value="default">사업 중요도·적용 관계</option><option value="name">기업명</option></select></label></div><div id="cf-output" aria-live="polite"></div><details class="surface" id="cf-admin-audit" hidden><summary>관리자 · 이번 분석 사용량</summary><div></div></details></div>`;
 const $=s=>root.querySelector(s),request=async(url,opts={})=>{const response=await fetch(url,{...opts,signal:abort.signal});const data=await response.json();if(!response.ok)throw Error(data.message||'연결 오류 · 다시 시도해 주세요.');return data;};
 const message=s=>{if(!dead)$('#cf-message').textContent=s;};
 function render(){if(dead||!current)return;$('#cf-output').innerHTML=deliveryMarkup(current,{marketFilter:$('#cf-filter').value,sort:$('#cf-sort').value});$('.cf-delivery-filters').hidden=!current.supported;}
 async function load(params,{fill=false}={}){try{message('저장된 자료를 확인하고 있습니다.');const r=await request('/api/catalyst/results?'+params);if(dead)return;current=r;if(fill){$('#cf-question').value=r.query;$('#cf-question-guidance').textContent=questionGuidance(r.query);}render();message('');if(r.analysisId){const u=new URL(location.href);u.searchParams.set('analysis',r.analysisId);u.searchParams.delete('q');window.history.replaceState({},'',u);}return r;}catch(e){if(dead)return null;if(params.has('q')){current=null;$('#cf-output').innerHTML='';$('.cf-delivery-filters').hidden=true;$('#cf-admin-audit').hidden=true;const u=new URL(location.href);u.searchParams.delete('analysis');u.searchParams.set('q',params.get('q'));window.history.replaceState({},'',u);}message(e.message);return null;}}
 async function usage(id){try{const r=await request('/api/catalyst/research/'+id+'/metrics');if(dead)return;$('#cf-admin-audit').hidden=false;const stages={};for(const s of r.steps)stages[s.stage]=(stages[s.stage]||0)+s.duration_ms;$('#cf-admin-audit>div').textContent=`AI ${r.usage.calls}회 · 입력 ${r.usage.inputTokens} / 출력 ${r.usage.outputTokens} / 합계 ${r.usage.totalTokens} 토큰 · 검색 ${r.searchUsage.reduce((n,s)=>n+s.requests,0)}회 · 결과 캐시 ${current?.freshness?.cacheHit?'적중':'서버 재분류'} · 단계별 기록 시간: ${Object.entries(stages).filter(([,ms])=>ms>0).map(([stage,ms])=>stage+' '+(ms/1000).toFixed(1)+'초').join(' / ')||'기록 없음'} · 화면 조회는 추가 호출 없음`;}catch{}}
 async function poll(){if(dead||!activeId)return;try{const execution=await request('/api/catalyst/research/'+activeId+'/execution');const r=await request('/api/catalyst/results?id='+encodeURIComponent(activeId));if(dead)return;current=r;render();const pending=['starting','running','cancel_requested'].includes(execution.state);message(execution.state==='cancel_requested'?'취소 요청됨 · 프로세스 종료 확인 중':pending?'한 건 분석 중 · 완료 후 자동으로 표시합니다.':r.failed||['failed','timed_out'].includes(execution.state)?'분석에 실패했습니다. 아래 원인을 확인해 주세요.':execution.state==='cancelled'?'분석이 취소됐습니다.':'분석이 완료됐습니다.');if(pending){timer=setTimeout(poll,2000);}else{$('#cf-cancel').hidden=true;$('#cf-new').disabled=!ready;void usage(activeId);activeId=null;}}catch(e){message(e.message);}}
 $('form').addEventListener('submit',e=>{e.preventDefault();if(activeId)return;const query=[$('#cf-question').value.trim(),$('#cf-hint').value.trim()].filter(Boolean).join(' · ');void load(new URLSearchParams({q:query,market:$('#cf-market').value}));},{signal:abort.signal});
 root.addEventListener('click',e=>{const group=e.target.closest('[data-question-group]');if(group){const selected=questionGroups.find(g=>g.id===group.dataset.questionGroup);if(!selected)return;root.querySelectorAll('[data-question-group]').forEach(b=>b.setAttribute('aria-pressed',String(b===group)));$('#cf-examples').innerHTML=selected.examples.map(q=>`<button type="button" data-question="${esc(q)}">${esc(q)}</button>`).join('');}const b=e.target.closest('[data-question]');if(b){$('#cf-question').value=b.dataset.question;$('#cf-question-guidance').textContent=questionGuidance(b.dataset.question);message('');$('#cf-question').focus();}},{signal:abort.signal});
 $('#cf-question').addEventListener('input',()=>{$('#cf-question-guidance').textContent=questionGuidance($('#cf-question').value);message('');},{signal:abort.signal});
 for(const selector of ['#cf-filter','#cf-sort'])$(selector).addEventListener('change',render,{signal:abort.signal});
 $('#cf-new').addEventListener('click',async()=>{if(!admin||!ready||activeId)return;const query=[$('#cf-question').value.trim(),$('#cf-hint').value.trim()].filter(Boolean).join(' · ');if(query.length<2||query.length>500){message('질문은 2~500자로 입력해 주세요.');return;}$('#cf-new').disabled=true;try{const j=await request('/api/catalyst/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query,market:$('#cf-market').value,mode:'normal'})});activeId=j.id;const u=new URL(location.href);u.searchParams.set('analysis',j.id);u.searchParams.delete('q');window.history.replaceState({},'',u);$('#cf-cancel').hidden=false;void poll();}catch(e){message(e.message);$('#cf-new').disabled=false;}},{signal:abort.signal});
 $('#cf-cancel').addEventListener('click',async()=>{if(!activeId)return;try{const r=await request('/api/catalyst/research/'+activeId+'/cancel',{method:'POST'});message(r.state==='cancel_requested'?'취소 요청됨 · 프로세스 종료 확인 중':'분석 프로세스 종료 상태를 확인하고 있습니다.');}catch(e){message(e.message);}},{signal:abort.signal});
 const params=new URLSearchParams(location.search);$('#cf-question').value=params.get('q')||'';$('#cf-question-guidance').textContent=questionGuidance($('#cf-question').value);$('#cf-hint').value=params.get('asset')||'';
 void request('/api/catalyst/config').then(c=>{if(dead)return;admin=c.admin;ready=c.ready;$('#cf-actions').hidden=!admin;$('#cf-new').disabled=!ready;if(admin&&current?.analysisId){void usage(current.analysisId);if(current.pending&&!activeId){activeId=current.analysisId;$('#cf-cancel').hidden=false;void poll();}}}).catch(e=>message(e.message));
 void load(new URLSearchParams(params.get('analysis')?{id:params.get('analysis')}:params.get('q')?{q:params.get('q')}:{latest:'1'}),{fill:!!params.get('analysis')||!params.get('q')}).then(r=>{if(admin&&r?.analysisId){void usage(r.analysisId);if(r.pending&&!activeId){activeId=r.analysisId;$('#cf-cancel').hidden=false;void poll();}}});
 return {destroy(){dead=true;abort.abort();clearTimeout(timer);}};
}
